"""Browser UI for measured local-model comparisons. No external frontend dependencies."""
PAGE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Compare systems · AgentReroute</title>
<style>
:root{--paper:#f7f6f2;--card:#fffefa;--ink:#252b2a;--muted:#6d756f;--line:#e0e3db;--blue:#294b76;--green:#38634e;--gold:#ad8543;--red:#a04c45;--mono:ui-monospace,SFMono-Regular,Consolas,monospace}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:14px system-ui,-apple-system,sans-serif}button,select,input{font:inherit}button,a,select,input,summary{outline-offset:4px}button,summary{cursor:pointer}button:disabled{cursor:default;opacity:.45}a{color:inherit}.shell{max-width:1340px;margin:auto;padding:0 28px 28px}
.nav{height:64px;display:flex;align-items:center;gap:26px;border-bottom:1px solid var(--line)}.brand{font:21px Georgia,serif;margin-right:12px;text-decoration:none}.brand b{color:var(--gold);font-size:23px;margin-right:8px}.nav-link{font-size:12px;text-decoration:none;padding:23px 0;color:var(--muted);border-bottom:2px solid transparent}.nav-link.active{color:var(--ink);border-bottom-color:var(--green)}.local{margin-left:auto;color:var(--green);font:10px var(--mono)}.local:before{content:'●';margin-right:7px}
.intro{padding:25px 0 19px}.intro h1{font:30px Georgia,serif;letter-spacing:-.6px;margin:0 0 7px}.intro p{font-size:13px;color:var(--muted);line-height:1.6;margin:0}.controls{display:grid;grid-template-columns:minmax(220px,1fr) minmax(240px,1.2fr) auto;gap:16px;align-items:end;background:var(--card);padding:15px 17px;border:1px solid var(--line);border-radius:8px}.field{min-width:0}.field label{display:block;font-size:11px;color:var(--muted);margin-bottom:7px}.field select{width:100%;background:var(--card);border:1px solid var(--line);border-radius:5px;color:var(--ink);padding:9px 28px 9px 10px;font-size:12px;text-overflow:ellipsis}.run-actions{display:flex;gap:7px}.button{border:1px solid var(--line);background:var(--card);color:var(--ink);border-radius:5px;padding:9px 13px;font-size:12px;white-space:nowrap}.button.primary{background:var(--green);color:white;border-color:var(--green)}.button.small{padding:6px 9px}.notice{font-size:11px;color:var(--muted);line-height:1.6;margin:9px 1px 0}.error{padding:11px 14px;border:1px solid #dfc3bf;background:#fcf0ee;color:#843d36;border-radius:6px;font-size:12px;white-space:pre-wrap;margin:12px 0}.error:empty{display:none}
.runbar{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:23px 0 12px}.runbar h2{font-size:13px;font-weight:500;margin:0}.status-line{font-size:11px;color:var(--muted);margin:5px 0 0}.playback{display:flex;align-items:center;gap:6px;flex-wrap:wrap}.playback input{width:135px;accent-color:var(--green)}#cursor-label{min-width:84px;color:var(--muted);font:10px var(--mono)}
.columns{display:grid;grid-template-columns:1fr 1fr;gap:18px}.system{min-width:0;display:flex;flex-direction:column;background:var(--card);border:1px solid var(--line);border-top:3px solid var(--blue);border-radius:8px;overflow:hidden}.system.reroute{border-top-color:var(--green)}.system-head{padding:17px 19px 13px;display:flex;align-items:center;justify-content:space-between;gap:12px}.system h2{font:26px Georgia,serif;margin:0 0 5px;letter-spacing:-.5px}.kicker{font-size:11px;color:var(--muted)}.badge{border:1px solid var(--line);border-radius:20px;padding:4px 8px;font-size:10px;color:var(--muted);white-space:nowrap}.badge.running{color:var(--blue);background:#edf2f8;border-color:#c6d5e5}.badge.completed{color:var(--green);background:#edf4ee;border-color:#c6d9cc}.badge.error,.badge.partial{color:var(--red);background:#faefeb;border-color:#e6cbc2}
.outcome{font-size:11px;line-height:1.7;color:var(--muted);background:#f7f8f3;border:1px solid var(--line);border-radius:6px;margin:0 18px 16px;padding:11px 13px;min-height:112px}.outcome strong{display:block;color:var(--ink);font-size:15px;font-weight:500;margin-bottom:4px}.outcome .good{color:var(--green)}.outcome .bad{color:var(--red)}.algorithm{padding:0 18px 16px;display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.stage{border:1px solid var(--line);background:#fafbf7;border-radius:5px;min-height:43px;padding:8px;font-size:10px;color:var(--muted);display:flex;align-items:center;gap:7px}.stage i{font:9px var(--mono);font-style:normal;color:#929a92}.stage.active{border-color:#9eb4cd;background:#edf2f8;color:var(--blue);box-shadow:inset 2px 0 var(--blue)}.reroute .stage.active{border-color:#a7c2b1;background:#edf4ee;color:var(--green);box-shadow:inset 2px 0 var(--green)}.stage.done{color:var(--ink);background:#f2f5ed}.stage.failed{color:var(--red);border-color:#dfbdb5;background:#fbefec}
.stats{display:grid;grid-template-columns:repeat(4,1fr);padding:12px 19px;border-block:1px solid var(--line);gap:12px}.stat strong{display:block;font-size:19px;font-weight:500;font-variant-numeric:tabular-nums}.stat span{font-size:10px;color:var(--muted);display:block;margin-top:4px}.section{padding:15px 19px}.section-title{font-size:11px;font-weight:500;color:var(--muted);margin:0 0 10px}.attribution{flex:1}.candidates{display:grid;gap:6px}.candidate{background:#f7f8f3;border-radius:5px;padding:9px 10px;display:grid;grid-template-columns:18px 1fr auto;gap:6px}.rank{font:11px var(--mono);color:var(--muted);padding-top:1px}.candidate b{font-size:12px;font-weight:500}.candidate small{display:block;color:var(--muted);font-size:10px;margin-top:4px;word-break:break-word}.score{font:11px var(--mono);color:var(--green);text-align:right}.empty{font-size:11px;color:#899087;line-height:1.7;margin:0}.warning{font-size:11px;color:var(--red);line-height:1.6;padding:10px 19px;background:#fcf2ef;border-top:1px solid #ecd6cf}.warning:empty{display:none}
.evidence{border-top:1px solid var(--line)}.evidence > summary{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:12px 19px;font-size:11px;color:var(--muted);list-style:none}.evidence > summary::-webkit-details-marker{display:none}.evidence > summary:after{content:'+';font-size:16px;line-height:1}.evidence[open] > summary:after{content:'−'}.evidence-count{margin-left:auto;font:10px var(--mono)}.evidence .section{padding-top:8px}.checks-line{display:flex;flex-wrap:wrap;gap:8px 12px;color:var(--muted);font:10px var(--mono);line-height:1.8}.violation{color:var(--red)}.log{max-height:210px;overflow:auto;display:grid;gap:5px}.log-row{text-align:left;border:0;background:#f5f6f0;border-radius:4px;padding:8px;font:10px var(--mono);color:var(--muted);width:100%;word-break:break-word}.log-row b{color:var(--ink);font-weight:400}.log-row.failed{background:#fbefec;color:var(--red)}
.supporting{margin-top:18px;background:var(--card);border:1px solid var(--line);border-radius:8px;overflow:hidden}.supporting > details + details{border-top:1px solid var(--line)}.input-run,.details-panel,.performance,.method{padding:0 18px}.supporting summary{font-size:12px;font-weight:500;padding:14px 0;color:var(--ink)}.supporting details[open]{padding-bottom:14px}.source-meta{color:var(--muted);font:10px var(--mono);line-height:1.8;margin:0 0 10px}.trace{display:flex;gap:7px;overflow:auto;padding-bottom:9px}.trace-step{flex:0 0 118px;border:1px solid var(--line);padding:9px;border-radius:5px;background:#f8f9f3;text-align:left;min-height:66px}.trace-step b{display:block;font:10px var(--mono);color:var(--blue);margin-bottom:7px}.trace-step span{font-size:10px;color:var(--muted)}.trace-step.focus{border-color:var(--green);background:#edf4ee}pre{white-space:pre-wrap;word-break:break-word;font:11px/1.7 var(--mono);color:var(--muted);max-height:300px;overflow:auto}.table-scroll{overflow:auto}.performance table{border-collapse:collapse;width:100%;font-size:12px}.performance td,.performance th{text-align:left;border-bottom:1px solid var(--line);padding:10px 12px}.performance th{font-size:10px;font-weight:500;color:var(--muted)}.performance p,.method p{font-size:11px;line-height:1.8;color:var(--muted);margin:10px 0 0}.footer{font:10px/1.7 var(--mono);color:var(--muted);margin-top:15px;overflow-wrap:anywhere}
@media(max-width:1050px){.controls{grid-template-columns:1fr 1fr}.run-actions{grid-column:1/-1}.runbar{align-items:flex-start;flex-direction:column;gap:12px}.playback input{width:170px}}
@media(max-width:760px){.shell{padding:0 15px 24px}.nav{gap:15px;height:60px}.brand{font-size:18px;margin-right:0}.nav-link{font-size:11px;padding:21px 0}.local{display:none}.intro{padding:22px 0 16px}.intro h1{font-size:27px}.controls{grid-template-columns:1fr;padding:14px}.run-actions{grid-column:auto}.columns{grid-template-columns:1fr}.playback{gap:5px}.playback input{width:105px}.system-head{padding:16px}.system h2{font-size:25px}.outcome{min-height:0}.stats{gap:8px}.stat strong{font-size:18px}.stage{padding:7px;font-size:10px}.evidence-count{font-size:9px}.performance td,.performance th{padding:9px 7px}}
</style></head><body><main id="comparison-app" class="shell">
<nav class="nav" aria-label="Main navigation"><a class="brand" href="/"><b>⚜</b>AgentReroute</a><a class="nav-link" href="/">Execution view</a><a class="nav-link active" href="/compare" aria-current="page">Compare systems</a><span class="local" id="connection">LOCAL OLLAMA</span></nav>
<header class="intro"><h1>Compare executions</h1><p>Same agent trace. Two approaches to finding and correcting the fault.</p></header>
<form id="run-form" class="controls"><div class="field"><label for="scenario">Scenario</label><select id="scenario" required><option value="">Loading scenarios…</option></select></div><div class="field"><label for="model">Ollama model</label><select id="model" required><option value="">Connecting to Ollama…</option></select></div><div class="run-actions"><button id="start-run" class="button primary" type="submit" disabled>Run comparison</button><button id="cancel-run" class="button" type="button" disabled>Stop</button></div></form>
<p class="notice">Recorded input & scripted user · Live Ollama inference · AgentReroute uses initial weights</p><div id="error" class="error" role="alert"></div>
<div class="runbar"><div><h2>Execution timeline</h2><p class="status-line" id="run-status" aria-live="polite">Ready when you are. Both systems receive the same recorded input.</p></div><div class="playback" aria-label="Shared event playback"><button class="button small" id="previous" type="button" aria-label="Previous event">←</button><button class="button small" id="play" type="button">Pause playback</button><button class="button small" id="next" type="button" aria-label="Next event">→</button><input id="cursor" type="range" min="0" max="0" value="0" aria-label="Event timeline"><span id="cursor-label">0 / 0 events</span><button class="button small" id="go-live" type="button">Go live</button></div></div>
<div class="columns" id="systems"></div>
<div class="supporting">
<details class="performance"><summary>Full performance comparison</summary><div class="table-scroll"><table><thead><tr><th>THIS EXECUTION</th><th>AGENTRX</th><th>AGENTREROUTE</th></tr></thead><tbody id="metrics"></tbody></table></div><p>Observed measurements for this run; policy scores are not calibrated failure probabilities.</p></details>
<details class="input-run"><summary>Shared input trace</summary><p class="source-meta" id="input-meta">The recorded multi-agent execution appears here when a comparison starts.</p><div class="trace" id="trace"></div><pre id="trace-detail">Select a step to inspect its messages and tool calls.</pre></details>
<details class="details-panel" id="event-inspector"><summary>Event inspector</summary><pre id="event-detail">Start a comparison to inspect its events.</pre></details>
<details class="method"><summary>How to read this comparison</summary><p>Both systems receive the same recorded retail trace and use the selected Ollama model. The original input and user are scripted; diagnosis and agent turns after rollback use real inference. AgentRx uses one final judge; AgentReroute combines three perspectives with initial policy weights, without a trained checkpoint. Both use the same repair engine.</p><p>Systems run sequentially to avoid competing for the GPU. Timings include model loading and queueing; unknown token totals remain blank. These are single-run observations, not benchmark accuracy. Policy scores are action-selection weights, not calibrated failure probabilities. “Task met” checks the actual retail state and required outputs after repair. Completed execution does not imply successful repair.</p></details>
</div><footer class="footer" id="artifacts">Requests, diagnosis and recovery artifacts are saved locally for each run.</footer>
</main><script>
'use strict';
const $=id=>document.getElementById(id), SIDES=['agentrx','agentreroute'];
const LABELS={agentrx:['AgentRx','Global constraints','Dynamic constraints','Guarded checks','Single judge','Shared repair','Verify outcome'],agentreroute:['AgentReroute','P1 · Intent & plan','P2 · Tool execution','P3 · Handoff & facts','Policy ranking','Shared repair','Verify + update']};
const S={events:[],cursor:0,following:true,playing:true,job:null,status:'idle',results:{},timer:null,loaded:false,trace:null,selectedStep:null};
function text(tag,value,cls){const el=document.createElement(tag);el.textContent=value??'';if(cls)el.className=cls;return el;}
function fmt(v,unit=''){return typeof v==='number'?v.toLocaleString(undefined,{maximumFractionDigits:2})+unit:'—';}
function showError(message){$('error').textContent=message||'';}
function stageFor(side,e){if(e.kind.startsWith('repair_')||(e.stage||'').startsWith('replay_agent'))return 4;if(e.kind==='verification_completed')return 5;if(e.kind==='attribution_completed')return 3;if(e.kind==='checks_completed')return side==='agentrx'?2:null;const stage=e.stage||'';if(side==='agentrx')return {global:0,dynamic:1,semantic:2,judge:3}[stage]??null;if(e.perspective)return {P1_INTENT_PLAN:0,P2_TOOL_EXECUTION:1,P3_HANDOFF_GROUNDING:2}[e.perspective]??null;return null;}
for(const side of SIDES){const card=text('section','',`system ${side==='agentreroute'?'reroute':''}`);card.id=side;card.setAttribute('aria-label',LABELS[side][0]+' execution');card.innerHTML=`<div class="system-head"><div><h2>${LABELS[side][0]}</h2><span class="kicker">${side==='agentrx'?'Constraints → single judge':'Three perspectives → policy ranking'}</span></div><span class="badge" id="${side}-status">Ready</span></div>
<div class="outcome" id="${side}-outcome"></div>
<div class="algorithm" id="${side}-stages" aria-label="Algorithm stages"></div>
<div class="stats"><div class="stat"><strong id="${side}-calls">—</strong><span>Model calls</span></div><div class="stat"><strong id="${side}-time">—</strong><span>Model time</span></div><div class="stat"><strong id="${side}-tokens">—</strong><span>Output tokens</span></div><div class="stat"><strong id="${side}-violations">—</strong><span>Violations</span></div></div>
<div class="section attribution"><h3 class="section-title">Likely fault</h3><div class="candidates" id="${side}-candidates"></div></div>
<div class="warning" id="${side}-warning" role="status"></div>
<details class="evidence" id="${side}-evidence"><summary>Checks & model requests <span class="evidence-count" id="${side}-evidence-count"></span></summary><div class="section"><h3 class="section-title">Checks & evidence</h3><div class="checks-line" id="${side}-checks">No checks completed yet.</div></div><div class="section"><h3 class="section-title">All model requests · select to inspect</h3><div class="log" id="${side}-log"></div></div></details>`;$('systems').append(card);LABELS[side].slice(1).forEach((name,i)=>{const el=text('div','','stage');el.id=side+'-stage-'+i;el.append(text('i',String(i+1).padStart(2,'0')),text('span',name));$(side+'-stages').append(el);});}
function fold(){const states=Object.fromEntries(SIDES.map(s=>[s,{status:'Ready',requests:[],metrics:{},checks:null,hypotheses:null,verification:null,stages:{},result:null}]));for(const e of S.events.slice(0,S.cursor)){const p=states[e.system];if(!p)continue;if(e.kind==='system_started')p.status='running';if(e.kind==='request_started'){p.requests.push({...e,state:'running'});p.metrics.model_calls=(p.metrics.model_calls||0)+1;}if(e.kind==='request_completed'||e.kind==='request_failed'){const row=p.requests.find(r=>r.request_id===e.request_id);if(row)Object.assign(row,e,{state:e.kind==='request_failed'?'failed':'completed'});}if(e.metrics)p.metrics={...e.metrics};const observedRequest=p.requests.find(r=>r.request_id===e.request_id);const stage=stageFor(e.system,{...e,perspective:e.perspective||observedRequest?.perspective});if(stage!==null){if(e.kind==='request_started'||e.kind==='repair_started')p.stages[stage]='active';else if(e.kind==='request_failed')p.stages[stage]='failed';else p.stages[stage]='done';}if(e.kind==='synthesis_summary'){p.synthesis=e.summary;for(const perspective of e.summary.failed_perspectives){const i=stageFor(e.system,{kind:'synthesis_summary',perspective});if(i!==null)p.stages[i]='failed';}}if(e.kind==='checks_completed'){p.checks=e.counts;p.seed_checks=e.seed_checks;p.checkRows=e.rows;}if(e.kind==='attribution_completed'){p.hypotheses=e.hypotheses;p.prediction=e.prediction;p.diagnosis_seconds=e.diagnosis_seconds;}if(e.kind==='repair_started')p.directive=e.directive;if(e.kind==='repair_replayed')p.replay=e;if(e.kind==='verification_completed')p.verification=e;if(e.kind==='system_finished'){p.status=e.result.status;p.result=e.result;p.metrics=e.result.metrics;if(e.result.error)p.error=e.result.error;}}
return states;}
function candidates(side,p){const box=$(side+'-candidates');box.replaceChildren();if(p.hypotheses===null){box.append(text('p','Waiting for attribution. No prediction has been made.','empty'));return;}if(!p.hypotheses.length){box.append(text('p','Attribution abstained or produced no repairable candidate.','empty'));return;}p.hypotheses.slice(0,3).forEach((c,i)=>{const row=text('div','','candidate'),body=text('div');body.append(text('b',`${c.agent} · step ${c.step_index}`),text('small',c.mode||c.category));const score=text('div',c.confidence==null?'Not reported':fmt(c.confidence),'score');score.append(text('small',side==='agentreroute'?'policy score':'confidence'));row.append(text('span',String(i+1).padStart(2,'0'),'rank'),body,score);box.append(row);});}
function renderTrace(){const input=S.events.find(e=>e.kind==='input_ready');if(!input){$('trace').replaceChildren();$('input-meta').textContent='The recorded multi-agent execution appears here when a comparison starts.';return;}S.trace=input.trace;$('input-meta').textContent=`${input.trace.steps.length} recorded steps · Input ${input.input_hash.slice(0,12)} · Identical input for both systems`;
const holder=$('trace');if(holder.dataset.hash===input.input_hash)return;holder.dataset.hash=input.input_hash;holder.replaceChildren();for(const step of input.trace.steps){const event=step.substeps[0]||{},b=text('button','','trace-step');b.type='button';b.append(text('b',`#${step.index} · ${event.role||'event'}`),text('span',event.name||(event.tool_calls||[])[0]?.name||String(event.content||'').slice(0,35)));b.onclick=()=>{holder.querySelectorAll('button').forEach(n=>n.classList.remove('focus'));b.classList.add('focus');$('trace-detail').textContent=JSON.stringify(step,null,2);};holder.append(b);}}
function render(){const panels=fold();for(const side of SIDES){const p=panels[side],badge=$(side+'-status');badge.textContent=p.status==='Ready'&&S.job?(['completed','error','canceled'].includes(S.status)&&S.cursor===S.events.length?'Not run':'Queued'):p.status.replace('_',' ');badge.className='badge '+p.status;for(let i=0;i<6;i++)$(side+'-stage-'+i).className='stage '+(p.stages[i]||'');$(side+'-calls').textContent=fmt(p.metrics.model_calls);$(side+'-tokens').textContent=fmt(p.metrics.completion_tokens);$(side+'-time').textContent=fmt(p.metrics.model_seconds,'s');$(side+'-violations').textContent=p.checks?fmt(p.checks.VIOL):'—';candidates(side,p);const checks=$(side+'-checks');checks.replaceChildren();if(p.checks){for(const key of ['SAT','VIOL','SKIP','ERROR'])checks.append(text('span',`${key} ${p.checks[key]}`,key==='VIOL'?'violation':''));checks.append(text('span',`${p.seed_checks||0} seed evaluations`));if(p.synthesis){const v=p.synthesis;checks.append(text('span',`${v.llm_constraints} model rules · ${v.llm_conclusive_checks} conclusive model checks`));if(v.state==='invalid_synthesis_fallback')checks.append(text('span',`Seed-only fallback: model rules rejected or generation failed (${v.failed_stages} stages).`,'violation'));else if(v.state==='valid_empty_synthesis')checks.append(text('span','Seed-only checks: model returned valid empty rule sets.'));else if(v.state==='partial_synthesis')checks.append(text('span','Some model rule generation failed validation.','violation'));if(v.rejected_constraints)checks.append(text('span',`${v.rejected_constraints} rejected rule outputs; details in synthesis event.`,'violation'));}}else checks.textContent='No checks completed yet.';const warning=$(side+'-warning');warning.textContent=p.synthesis?.state==='invalid_synthesis_fallback'?'Seed-only fallback: model rules rejected or generation failed.':p.synthesis?.state==='partial_synthesis'?'Some model rules failed validation. Expand checks for details.':'';$(side+'-evidence-count').textContent=p.requests.length?`${p.requests.length} calls · ${p.checks?Object.values(p.checks).reduce((a,b)=>a+b,0):'—'} checks`:'';const log=$(side+'-log');log.replaceChildren();for(const request of p.requests){const button=text('button','','log-row '+(request.state==='failed'?'failed':''));button.type='button';button.append(text('b',`${String(request.request_id).padStart(2,'0')}  ${request.stage}`),text('span',` · ${request.state}${request.seconds!=null?' · '+fmt(request.seconds,'s'):''}`));button.onclick=()=>{S.following=false;S.playing=false;S.cursor=S.events.findIndex(e=>e.seq===request.seq)+1;render();$('event-inspector').open=true;$('event-inspector').scrollIntoView({behavior:'smooth',block:'nearest'});};log.append(button);}if(!p.requests.length)log.append(text('p','Requests will appear here as they are sent.','empty'));const out=$(side+'-outcome');out.replaceChildren();if(p.error)out.append(text('div',p.error,'bad'));else if(p.verification){const v=p.verification,goal=v.task_outcome.after.reward===1;out.append(text('strong',goal?'Task met':'Task not met',goal?'good':'bad'));out.append(text('div',`Repair: ${v.verification.accepted?'accepted':'not accepted / no intervention'} · Decision: ${v.decision.status}.`));out.append(text('div',`State ${v.task_outcome.after.state_ok?'matched':'not matched'} · Required outputs ${v.task_outcome.after.missing_outputs.length?'missing':'present'}.`));if(v.policy_update)out.append(text('div',`Policy updated · Feedback reward ${fmt(v.policy_update.reward)}`));}else if(p.directive){out.append(text('strong',`Rollback to step ${p.directive.rollback_step}`),text('div',p.directive.text));}else out.append(text('p','Waiting for attribution and a repair decision.','empty'));}
const rows=[['Attribution elapsed',p=>fmt(p.diagnosis_seconds,'s')],['Total elapsed',p=>fmt(p.result?.metrics.elapsed_seconds,'s')],['Model requests',p=>fmt(p.metrics.model_calls)],['Input tokens',p=>fmt(p.metrics.prompt_tokens)],['Output tokens',p=>fmt(p.metrics.completion_tokens)],['Check violations',p=>p.checks?fmt(p.checks.VIOL):'—'],['Task met after intervention',p=>p.verification?(p.verification.task_outcome.after.reward===1?'Yes':'No'):'—']];$('metrics').replaceChildren();for(const [name,value] of rows){const tr=text('tr');tr.append(text('td',name),...SIDES.map(s=>text('td',value(panels[s]))));$('metrics').append(tr);}$('cursor').max=S.events.length;$('cursor').value=S.cursor;$('cursor-label').textContent=`${S.cursor} / ${S.events.length} events`;$('play').textContent=S.playing?'Pause playback':'Play events';$('previous').disabled=S.cursor===0;$('next').disabled=S.cursor===S.events.length;$('run-status').textContent=S.job?`${S.status}${S.following?' · following live events':' · historical playback'}${S.status==='running'?' · model calls can take several minutes':''}`:'Ready when you are. Both systems receive the same recorded input.';const e=S.events[S.cursor-1];$('event-detail').textContent=e?JSON.stringify(e,null,2):'No event selected.';renderTrace();}
async function api(path,options={}){const response=await fetch(path,options);let data;try{data=await response.json();}catch{throw Error('The local server returned an unreadable response.');}if(!response.ok)throw Error(data.error||`Request failed (${response.status})`);return data;}
function busy(value){$('start-run').disabled=value||!S.loaded||!!$('model').selectedOptions[0]?.disabled;$('cancel-run').disabled=!value;$('scenario').disabled=value;$('model').disabled=value;}
async function poll(){if(!S.job)return;try{const data=await api('/api/comparisons/'+S.job+'?after='+S.events.length);S.status=data.status;$('scenario').value=data.scenario;if(![...$('model').options].some(o=>o.value===data.model)){const recorded=text('option',data.model+' (recorded run)');recorded.value=data.model;recorded.disabled=true;$('model').append(recorded);}$('model').value=data.model;for(const e of data.events)if(!S.events.some(x=>x.seq===e.seq))S.events.push(e);if(S.following)S.cursor=S.events.length;$('artifacts').textContent='Artifacts: '+data.artifact_dir;busy(!['completed','error','canceled'].includes(data.status));if(data.cancel_requested&&data.status==='running')showError('Stop requested. The current Ollama call will finish; no further model requests will be sent.');if(data.cancel_requested&&data.status==='canceled')showError('Stopped. Completed requests remain available for inspection.');if(data.status==='error'){const error=S.events.findLast(e=>e.kind==='job_error');if(error)showError(error.error);}render();if(!['completed','error','canceled'].includes(data.status))S.timer=setTimeout(poll,900);}catch(error){showError(error.message);busy(false);}}
$('run-form').onsubmit=async e=>{e.preventDefault();if(!$('model').value)return;busy(true);showError('');try{const job=await api('/api/comparisons',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scenario:$('scenario').value,model:$('model').value})});clearTimeout(S.timer);S.job=job.id;S.events=[];S.cursor=0;S.following=true;S.playing=true;S.status='running';$('trace').dataset.hash='';$('trace-detail').textContent='Select a step to inspect its messages and tool calls.';sessionStorage.setItem('comparison-job',job.id);history.replaceState(null,'','/compare?run='+job.id);render();poll();}catch(error){showError(error.message);busy(false);}};
$('cancel-run').onclick=async()=>{try{await api('/api/comparisons/'+S.job+'/cancel',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});showError('Stop requested. Waiting for the current model call to finish.');}catch(error){showError(error.message);}};
function move(value){S.cursor=Math.max(0,Math.min(S.events.length,value));S.following=false;S.playing=false;render();}$('previous').onclick=()=>move(S.cursor-1);$('next').onclick=()=>move(S.cursor+1);$('cursor').oninput=e=>move(Number(e.target.value));$('go-live').onclick=()=>{S.following=true;S.playing=true;S.cursor=S.events.length;render();};$('play').onclick=()=>{S.playing=!S.playing;S.following=false;render();};setInterval(()=>{if(S.playing&&!S.following&&S.cursor<S.events.length){S.cursor++;render();}},800);
async function init(){render();try{const data=await api('/api/scenarios');$('scenario').replaceChildren();for(const row of data){const o=text('option',row.title);o.value=row.id;$('scenario').append(o);}}catch(error){showError(error.message);return;}
try{const models=await api('/api/models');$('model').replaceChildren();if(!models.models.length)throw Error('Ollama has no installed models. Install a model, then reload this page.');for(const name of models.models){const o=text('option',name);o.value=name;$('model').append(o);}S.loaded=true;busy(false);}catch(error){showError(error.message);$('connection').textContent='CONNECTION NEEDS ATTENTION';}
const saved=new URLSearchParams(location.search).get('run')||sessionStorage.getItem('comparison-job');if(saved){S.job=saved;await poll();}}
$('model').onchange=()=>{if(['idle','completed','error','canceled'].includes(S.status))busy(false);};init();
</script></body></html>'''
